#!/usr/bin/env python3
"""WISDOHM 2.6: one CLI, SQLite memory, YAML policy."""
import argparse
import hashlib
import json
from pathlib import Path
import sys
sys.dont_write_bytecode = True
from common import need, parse_json, project_path
from store import Store

VERSION = '2.6.0'


def migrate(store, source):
    source = Path(source).resolve()
    index = project_path(source, '.wisdohm/state/index.json')
    entries, sessions, hashes = [], [], {}
    paths = {}
    if index.exists():
        catalog = parse_json(index.read_text())
        for category, files in catalog.get('memory', {}).items():
            kind = {'changelog':'changelog','codebase':'codebase','progress':'progress',
                    'decisions':'decision','features':'feature','ui':'registry'}.get(category, 'progress')
            for name in files:
                paths[name] = kind
        for name in catalog.get('registries', {}).values():
            paths.setdefault(name, 'registry')
        hashes['.wisdohm/state/index.json'] = hashlib.sha256(index.read_bytes()).hexdigest()
    for name, kind in sorted(paths.items()):
        path = project_path(source, name, write=True)
        if not path.exists():
            continue
        raw = path.read_text(); hashes[name] = hashlib.sha256(raw.encode()).hexdigest()
        if raw.strip():
            entries.append({'kind':kind, 'key':name, 'body':{'text':raw,'imported_from':name,
                            'source_sha256':hashes[name], 'legacy':True}})
    folder = project_path(source, '.wisdohm/state/agents')
    if folder.exists():
        for path in sorted(folder.glob('*.json')):
            relative = path.relative_to(source).as_posix()
            raw = project_path(source, relative, write=True).read_text()
            previous = parse_json(raw); hashes[relative] = hashlib.sha256(raw.encode()).hexdigest()
            identity = previous.get('id')
            need(isinstance(identity,str) and identity, 'legacy session lacks identity')
            sessions.append(dict(previous, schema_version=2, id=identity, root=str(store.root),
                                 kind=previous.get('kind','maintenance'), owner=previous.get('owner','legacy'),
                stage='HANDOVER', write=[], read=[], rules=[], verify=[],
                task=previous.get('task','Imported legacy task'),
                summary=previous.get('summary','Historical task imported; current verification required.'),
                blockers=previous.get('blockers',[]), checks=[], receipt={},
                legacy_checks=previous.get('checks',[]),
                                 legacy_scope=previous.get('write',[]), legacy_origin_root=previous.get('root'),
                                 context=None, outputs=None, memory=None, _legacy=True,
                                 next='Start a successor task; imported verification is historical.'))
    fingerprint = hashlib.sha256(json.dumps(hashes,sort_keys=True).encode()).hexdigest()
    return store.import_legacy(entries, sessions, str(source), fingerprint)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--target', type=Path, default=Path(__file__).resolve().parent.parent)
    commands = parser.add_subparsers(dest='command',required=True)
    agent = commands.add_parser('agent');agent.add_argument('argv',nargs=argparse.REMAINDER)
    db = commands.add_parser('db');db.add_argument('action',choices=['init','status','history','memory','backup','migrate'])
    db.add_argument('--id');db.add_argument('--kind');db.add_argument('--output',type=Path);db.add_argument('--from',dest='source',type=Path)
    args = parser.parse_args();root=args.target.resolve()
    try:
        need(root.is_dir(), 'project directory must exist')
        if args.command == 'agent':
            need('(version 2.6.0)' in project_path(root,'.wisdohm/BOOT.md').read_text(),
                 'WISDOHM 2.6 project entry required; deploy/review migration first')
            from session import main as agent_main
            return agent_main(root,args.argv)
        if args.action in {'status','history','memory'} and not (root/'.wisdohm/memory.sqlite').exists():
            print(json.dumps({'version':VERSION,'memory':'not initialized','tasks':[]}));return 0
        store=Store(root)
        if args.action=='init':result={'version':VERSION,'database':str(store.path),'status':'ready'}
        elif args.action=='status':
            result={'version':VERSION,'tasks':[{k:s.get(k) for k in ['id','kind','owner','task','stage','next']}
                                              for s in store.sessions()], 'memory_records':len(store.records())}
        elif args.action=='memory':result=store.records(args.kind)
        elif args.action=='history':result=store.history(args.id)
        elif args.action=='backup':
            need(args.output is not None,'backup requires --output FILE');store.backup(args.output)
            result={'backup':str(args.output),'status':'saved'}
        else:result=migrate(store,args.source or root)
        print(json.dumps(result,indent=2));return 0
    except Exception as exc:
        print(json.dumps({'action':'stop','error':str(exc)}),file=sys.stderr);return 1


if __name__=='__main__':raise SystemExit(main())
